update ord_dis_presale_activity
set status = #{activity.status} ,update_time = #{activity.updateTime},updater =
#{activity.updater}
where id = #{activity.id}

    AND status = #{beforeStatus}

mapper.select:
SELECT pa.id,pa.presale_activity_no,ps.store_code,pg.goods_code,pa.begin_order_date,pa.end_order_date
FROM ord_dis_presale_activity pa
INNER JOIN ord_dis_presale_activity_store ps on ps.presale_activity_id = pa.id
INNER JOIN ord_dis_presale_activity_goods pg on pg.presale_activity_id = pa.id
where 1 = 1
 and pa.`status` in

    #{status}

and ps.store_code in

    #{storeCode}

and pg.goods_code in

    #{goodsCode}


    and pg.is_gift = #{isGift}


    and pa.id != #{id}

and pa.is_delete = 0

SELECT pa.id, pa.presale_activity_no, pa.status, (select count(1) from ord_dis_presale_activity_goods where presale_activity_id = pa.id) total_goods_qty, (select count(1) from ord_dis_presale_activity_store where presale_activity_id = pa.id) total_store_qty, pa.begin_sale_date, pa.end_sale_date, pa.begin_order_date, pa.end_order_date, pa.creator, pa.create_time, pa.updater, pa.update_time FROM ord_dis_presale_activity pa WHERE is_delete = 0
and pa.status = #{status}
and exists(select 1 from ord_dis_presale_activity_goods pg where pg.presale_activity_id = pa.id and pg.goods_code = #{goodsCode})
and pa.presale_activity_no = #{presaleActivityNo}
and pa.begin_sale_date >= #{beginSaleDate}
and pa.end_sale_date <= #{endSaleDate}
and pa.begin_order_date >= #{beginOrderDate}
and pa.end_order_date <= #{endOrderDate}
and exists(select 1 from ord_dis_presale_activity_store ps where ps.presale_activity_id = pa.id and ps.store_code = #{storeCode})
and pa.biz_org_code = #{bizOrgCode}
ORDER BY pa.id DESC
